 const wte=vocab*dim, lm=vocab*dim;
 const ve=veLayers.length*vocab*nh*HD;
 const mat=depth*(4*dim*dim+2*dim*4*dim);
 let nS=0,nL=0;
 for(let i=0;i<depth;i++){ let c="SSSL"[i%4]; if(i===depth-1)c="L"; if(c==="S")nS++; else nL++; }
 const eff=nS*1024+nL*2048;
 const flops=6*mat+12*nh*128*eff;
 const tot=wte+lm+ve+mat;
 console.log({depth,dim,params_M:Math.round(tot/1e5)/10,mat_M:Math.round(mat/1e5)/10,flops_M:Math.round(flops/1e5)/10});
}
for(const d of [4,5,6,8,10]) count(d);
'

